import{_ as o,o as t,c as n,a2 as a}from"./chunks/framework.CPzUcv0I.js";const g=JSON.parse('{"title":"Démarrage Rapide","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/players/getting-started.md","filePath":"fr/guide/players/getting-started.md"}'),r={name:"fr/guide/players/getting-started.md"};function i(s,e,l,c,d,u){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="demarrage-rapide" tabindex="-1">Démarrage Rapide <a class="header-anchor" href="#demarrage-rapide" aria-label="Permalink to &quot;Démarrage Rapide&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Minecraft-Vanilla%20%26%20Moddé-green.svg" alt="Minecraft"><img src="https://img.shields.io/badge/Plateforme-Windows%20%7C%20macOS%20%7C%20Linux-blue.svg" alt="Plateformes"><img src="https://img.shields.io/badge/Licence-MIT-orange.svg" alt="Licence"></div><p>Bienvenue sur la documentation officielle de <strong>Gens Launcher</strong>. Ce guide vous accompagne pas à pas dans la découverte du lanceur, la connexion à votre compte Minecraft et le lancement de votre première partie.</p><hr><h2 id="pourquoi-gens-launcher" tabindex="-1">Pourquoi Gens Launcher ? <a class="header-anchor" href="#pourquoi-gens-launcher" aria-label="Permalink to &quot;Pourquoi Gens Launcher ?&quot;">​</a></h2><p>Gens Launcher a été conçu pour allier <strong>performance maximale</strong>, <strong>ergonomie moderne</strong> et <strong>sécurité sans compromis</strong> :</p><ul><li><strong>Légèreté et fluidité :</strong> Développé sans dépendances superflues, le lanceur démarre instantanément et consomme un minimum de ressources.</li><li><strong>Gestion Multi-Modloaders :</strong> Créez des profils <strong>Vanilla</strong>, <strong>Fabric</strong>, <strong>Forge</strong>, <strong>Quilt</strong> ou <strong>NeoForge</strong> en quelques clics sans configuration complexe.</li><li><strong>Synchronisation Cloud Horizon :</strong> Grâce au moteur compagnon <strong>Gens-Horizon</strong>, synchronisez automatiquement vos mondes, paramètres et mods avec Google Drive, Dropbox ou OneDrive.</li><li><strong>Catalogue de Contenu Intégré :</strong> Téléchargez mods, packs de textures et shaders directement depuis Modrinth et CurseForge.</li><li><strong>Respect de la Vie Privée :</strong> 100% open-source sous licence MIT, sans télémétrie ni pistage commercial.</li></ul><hr><h2 id="connexion-a-votre-compte-minecraft" tabindex="-1">Connexion à votre Compte Minecraft <a class="header-anchor" href="#connexion-a-votre-compte-minecraft" aria-label="Permalink to &quot;Connexion à votre Compte Minecraft&quot;">​</a></h2><p>Gens Launcher prend en charge deux types d&#39;authentification :</p><h3 id="_1-compte-officiel-microsoft-recommande" tabindex="-1">1. Compte Officiel Microsoft (Recommandé) <a class="header-anchor" href="#_1-compte-officiel-microsoft-recommande" aria-label="Permalink to &quot;1. Compte Officiel Microsoft (Recommandé)&quot;">​</a></h3><ol><li>Cliquez sur le bouton <strong>Se connecter avec Microsoft</strong> situé en haut à droite de l&#39;écran d&#39;accueil.</li><li>Une fenêtre s&#39;ouvre avec un code court (ex: <code>B49X-Y2K9</code>) et un lien vers <code>microsoft.com/link</code>.</li><li>Validez la connexion dans votre navigateur internet habituel avec votre compte Microsoft détenant Minecraft Java Edition.</li><li>Le lanceur détecte instantanément l&#39;approbation, récupère votre skin 3D et chiffre vos identifiants en toute sécurité dans le trousseau de votre système d&#39;exploitation.</li></ol><div class="tip custom-block"><p class="custom-block-title">Sécurité Maximale</p><p>Gens Launcher ne voit et ne stocke jamais votre mot de passe Microsoft. L&#39;authentification utilise le protocole officiel OAuth2 Device Code Flow de Microsoft.</p></div><h3 id="_2-mode-hors-ligne-offline" tabindex="-1">2. Mode Hors-Ligne (Offline) <a class="header-anchor" href="#_2-mode-hors-ligne-offline" aria-label="Permalink to &quot;2. Mode Hors-Ligne (Offline)&quot;">​</a></h3><p>Si vous ne disposez pas d&#39;une connexion Internet ou souhaitez jouer sur un réseau local :</p><ol><li>Cliquez sur l&#39;option <strong>Mode Hors-Ligne / Pseudo Local</strong>.</li><li>Renseignez simplement le pseudonyme de votre choix.</li><li>Vous pouvez lancer toutes vos instances préalablement installées.</li></ol><hr><h2 id="decouverte-de-l-interface" tabindex="-1">Découverte de l&#39;Interface <a class="header-anchor" href="#decouverte-de-l-interface" aria-label="Permalink to &quot;Découverte de l&#39;Interface&quot;">​</a></h2><p>L&#39;interface de Gens Launcher est articulée autour de 4 zones clés :</p><ol><li><strong>La Galerie d&#39;Instances :</strong> Présente visuellement toutes vos configurations de jeu avec leurs versions Minecraft, leurs modloaders et le statut de synchronisation cloud.</li><li><strong>Le Bouton d&#39;Action Rapide :</strong> Permet de lancer en un clic l&#39;instance sélectionnée. Un simulateur dynamique affiche la progression détaillée (téléchargement des assets, patch Delta Sync, initialisation de la JVM).</li><li><strong>Le Gestionnaire de Contenu :</strong> Onglet dédié pour ajouter des mods, shaders ou packs de textures en direct sans quitter le lanceur.</li><li><strong>Le Panneau Paramètres :</strong> Personnalisation des thèmes, allocation de mémoire RAM, choix de la version de Java et association aux services Cloud.</li></ol><hr><h2 id="etapes-suivantes" tabindex="-1">Étapes Suivantes <a class="header-anchor" href="#etapes-suivantes" aria-label="Permalink to &quot;Étapes Suivantes&quot;">​</a></h2><ul><li><a href="./installation">Guide d&#39;Installation détaillé sur tous les systèmes d&#39;exploitation</a></li><li><a href="./instances-and-mods">Créer et configurer des Instances et installer des Mods</a></li><li><a href="./cloud-sync">Activer la Synchronisation Cloud Horizon</a></li><li><a href="./troubleshooting">Résolution des problèmes fréquents</a></li></ul>',23)])])}const p=o(r,[["render",i]]);export{g as __pageData,p as default};
